INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 2, 'theory', 'Quiz: arrays and strings');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 2, 0, 'An array starts at address 2000 and each element takes 4 bytes. At what address does the element with index 10 live?', '["2010", "2040", "2044", "You have to walk past ten elements to find out"]', 1, 'Address = start + index × size = 2000 + 10 · 4 = 2040. One multiplication and one addition, so access by index does not depend on the length of the array.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 2, 1, 'When a dynamic array fills up, it grows its capacity by 10 cells instead of doubling. What happens over a million appends?', '["Nothing: the cost of an append is still amortized constant", "Memory runs out before time does", "The total copying work grows to quadratic", "The array gets slower at reading by index"]', 2, 'There will be a hundred thousand copies, and each drags everything accumulated: tens of billions of operations. With doubling, the sum of copies 1 + 2 + 4 + … is less than 2n.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 2, 2, 'At which position in an array is inserting a new element the most expensive?', '["At the end", "In the middle", "At the start", "The same everywhere: shifting is always O(n)"]', 2, 'Inserting at the start shifts all n elements, in the middle half of them, at the end none. So constant insertions at the start are a signal to take a queue or a list.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 2, 3, 'You need to find the sum over an arbitrary range of an array of a million elements a thousand times. What should you choose?', '["Compute the sum with a loop over the range each time", "Sort the array and use binary search", "Build prefix sums once: the answer is the difference of two numbers", "Store the array in a dictionary"]', 2, 'Preparation is one pass, and each query is two lookups and a subtraction. A loop over the range is up to a billion operations in total.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 2, 4, 'Why can building a long string in a loop with s += c turn into a square?', '["Concatenation can''t handle Unicode", "Strings are immutable: every append copies the whole accumulated string", "The interpreter checks the string for being an anagram", "Each character is stored as a separate object in a hash table"]', 1, '1 + 2 + 3 + … characters get copied, which is on the order of n²/2 operations. The cure: collect pieces in a list and join them once with the join method.');
